import urllib.request, json
for repo in ['biocontainers/seurat','biocontainers/r-seurat','biocontainers/seurat-scripts']:
    url=f'https://quay.io/api/v1/repository/{repo}/tag/?limit=10&onlyActiveTags=true'
    print('\\nREPO',repo)
    try:
        req=urllib.request.Request(url,headers={'User-Agent':'codex'})
        with urllib.request.urlopen(req,timeout=30) as r: data=json.load(r)
        for t in data.get('tags',[])[:10]:
